WITH base AS (SELECT *, CAST(rating AS INT) AS rating_int FROM suppliers WHERE country NOT IN ('DE', 'US', 'JP')), with_last AS (SELECT s.id, s.country, s.rating_int, latest.cost FROM base s JOIN LATERAL (SELECT c.cost FROM products c WHERE c.supplier_id = s.id ORDER BY c.stock_qty DESC, c.id DESC LIMIT 1) latest ON TRUE), latest AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY country ORDER BY cost DESC, id) AS dedup_rank FROM with_last) t WHERE dedup_rank = 1), with_last_suppliers AS (SELECT s.id, s.country, s.rating_int, s.cost, s.dedup_rank, top1.price FROM latest s LEFT JOIN LATERAL (SELECT c.price FROM products c WHERE c.supplier_id = s.id ORDER BY c.cost DESC, c.id DESC LIMIT 1) top1 ON TRUE), with_latest AS (SELECT s.*, x.product_cost, x.product_brand FROM with_last_suppliers s JOIN LATERAL (SELECT c.cost AS product_cost, c.brand AS product_brand FROM products c WHERE c.supplier_id = s.id ORDER BY c.launch_date DESC, c.id DESC LIMIT 1) x ON TRUE) SELECT country, COUNT_IF(product_brand = 'Globex') AS globex_events, ROUND(SUM(product_cost) / NULLIF(COUNT(CASE WHEN product_brand = 'Acme' THEN 1 END), 0), 2) AS product_cost_per_acme FROM with_latest GROUP BY country;
